    if (isNaN(bump) || bump === 0) { return false }
    var district = String(districtId)
    var stratum = String(stratumId)
    var matched = false
    for (var i = 0; i < state.blocks.length; i++) {
        var block = state.blocks[i]
        if (block.district.id !== district || block.demographic.id !== stratum) { continue }
        block.prosperity = clampProsperity(
            (block.prosperity ?? PROSPERITY_BLOCK_BASELINE) + bump
        )
        matched = true
        break
    }
    if (!matched) { return false }
    if (typeof Q.qified_block_prosperity === 'function') {
        Q.qified_block_prosperity()
    }
    if (typeof Q.syncStratumProsperityAverages === 'function') {
        Q.syncStratumProsperityAverages()
    }
    return true
}

